//! [`Visibility`] — the computed value of the `visibility` property (CSS 2.2 §11.2).
//!
//! Controls whether the boxes generated by an element are rendered.
//! Invisible boxes still affect layout (unlike `display: none`).
//! Descendants of a hidden box are rendered if they specify `visibility: visible`.

use core::fmt;
use core::str::FromStr;

use thiserror::Error;

/// A `visibility` keyword this cut does not carry.
#[derive(Clone, Debug, PartialEq, Eq, Error)]
#[error("unsupported visibility keyword `{0}`")]
pub struct ParseVisibilityError(String);

/// How an element's generated box is rendered.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Visibility {
    /// The generated box is visible.
    #[default]
    Visible,
    /// The generated box is invisible (nothing is drawn), but still affects layout.
    Hidden,
    /// In tables, removes a row or column without affecting table geometry;
    /// outside tables, treated as `hidden` (CSS 2.2 §11.2).
    Collapse,
}

impl Visibility {
    /// Whether this box should be painted.
    #[must_use]
    pub const fn is_visible(self) -> bool {
        matches!(self, Self::Visible)
    }

    /// The stylesheet keyword for this value.
    #[must_use]
    pub const fn keyword(self) -> &'static str {
        match self {
            Self::Visible => "visible",
            Self::Hidden => "hidden",
            Self::Collapse => "collapse",
        }
    }
}

impl fmt::Display for Visibility {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.keyword())
    }
}

impl FromStr for Visibility {
    type Err = ParseVisibilityError;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        match text {
            "visible" => Ok(Self::Visible),
            "hidden" => Ok(Self::Hidden),
            "collapse" => Ok(Self::Collapse),
            other => Err(ParseVisibilityError(other.to_owned())),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keyword_round_trips_and_unknown_is_typed() {
        for visibility in [
            Visibility::Visible,
            Visibility::Hidden,
            Visibility::Collapse,
        ] {
            assert_eq!(visibility.keyword().parse(), Ok(visibility));
        }
        assert_eq!(
            "transparent".parse::<Visibility>(),
            Err(ParseVisibilityError("transparent".to_owned()))
        );
    }

    #[test]
    fn visibility_is_visible_semantics() {
        assert!(Visibility::Visible.is_visible());
        assert!(!Visibility::Hidden.is_visible());
        assert!(!Visibility::Collapse.is_visible());
    }
}
